/** Label for a link that follows block content when nothing names its target. */
export const BLOCK_LINK_LABEL = 'Open';
export const FIRST_PARTY_MARKDOWN_COMPONENT_SOURCE = `
export const Note = ({ children }) => <blockquote>{"[!NOTE]\\n\\n"}{children}</blockquote>;

export const Info = ({ children }) => <blockquote>{"[!NOTE]\\n\\n"}{children}</blockquote>;

export const Tip = ({ children }) => <blockquote>{"[!TIP]\\n\\n"}{children}</blockquote>;

export const Check = ({ children }) => <blockquote>{"[!TIP]\\n\\n"}{children}</blockquote>;

export const Warning = ({ children }) => <blockquote>{"[!WARNING]\\n\\n"}{children}</blockquote>;

export const Danger = ({ children }) => <blockquote>{"[!CAUTION]\\n\\n"}{children}</blockquote>;

export const Card = ({ title = "", href = "", description = "", children }) => title === "" ? <blockquote>{(children ?? "") === "" ? description : children}{href === "" ? "" : <>{"\\n\\n"}<a href={href}>${BLOCK_LINK_LABEL}</a></>}</blockquote> : <blockquote><strong><a href={href}>{title}</a></strong>{"\\n\\n"}{(children ?? "") === "" ? description : children}</blockquote>;

export const Accordion = ({ title = "", description = "", children }) => <blockquote>{title === "" ? "" : <><strong>{title}</strong>{"\\n\\n"}</>}{description === "" ? "" : <>{description}{"\\n\\n"}</>}{children}</blockquote>;

export const ParamField = ({ path = "", body = "", query = "", header = "", type = "", required = false, deprecated = false, default: defaultValue = "", children }) => (path || body || query || header) === "" ? <>{children}</> : <>{"**" + (path || body || query || header) + "**"}{type === "" ? "" : " \\\`" + type + "\\\`"}{required ? " *required*" : ""}{deprecated ? " *deprecated*" : ""}{defaultValue === "" ? "" : " (default: " + defaultValue + ")"}{"\\n\\n"}{children}</>;

export const ResponseField = ({ name = "", type = "", required = false, deprecated = false, default: defaultValue = "", children }) => name === "" ? <>{children}</> : <>{"**" + name + "**"}{type === "" ? "" : " \\\`" + type + "\\\`"}{required ? " *required*" : ""}{deprecated ? " *deprecated*" : ""}{defaultValue === "" ? "" : " (default: " + defaultValue + ")"}{"\\n\\n"}{children}</>;

export const Steps = ({ children }) => <>{children}</>;

export const Step = ({ title = "", stepNumber = 1, titleSize = "p", children }) => <>{"\\n\\n"}{titleSize === "h2" ? "## " : titleSize === "h3" ? "### " : titleSize === "h4" ? "#### " : "**"}{title === "" ? "Step " + stepNumber : stepNumber + ". " + title}{titleSize === "h2" || titleSize === "h3" || titleSize === "h4" ? "" : "**"}{"\\n\\n"}{children}{"\\n\\n"}</>;

export const Tooltip = ({ tip = "", children }) => tip === "" ? <>{children}</> : <>{children}{" (" + tip + ")"}</>;

export const Frame = ({ caption = "", children }) => caption === "" ? <>{children}</> : <>{children}{"\\n\\n"}{caption}</>;

export const Update = ({ label = "", description = "", children }) => <>{label === "" ? "" : <><strong>{label}</strong>{"\\n\\n"}</>}{description === "" ? "" : <>{description}{"\\n\\n"}</>}{children}</>;

export const Tile = ({ href = "", title = "", "aria-label": ariaLabel = "", description = "", children }) => <>{(title || ariaLabel) === "" ? "" : href === "" ? <><strong>{title || ariaLabel}</strong>{"\\n\\n"}</> : <><a href={href}>{title || ariaLabel}</a>{"\\n\\n"}</>}{description === "" ? "" : <>{description}{"\\n\\n"}</>}{children}</>;

export const Prompt = ({ description = "", children }) => <>{description === "" ? "" : <>{description}{"\\n\\n"}</>}{children}</>;

export const Color_Item = ({ name = "", value = "" }) => <>{name === "" ? "" : "**" + name + "** "}{typeof value === "string" ? "\\\`" + value + "\\\`" : "\\\`" + value.light + "\\\` (light), \\\`" + value.dark + "\\\` (dark)"}{"\\n\\n"}</>;
`;
